#!/usr/bin/env python3
"""Alert when too many AnarchySubjects sit in a pending state."""

STUCK_MINUTES = 30
WARN_COUNT = 3
CRIT_COUNT = 5

def classify(stuck):
    if stuck >= CRIT_COUNT:
        return 2
    if stuck >= WARN_COUNT:
        return 1
    return 0

